from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject
from taf.gnb.oam.coam.vdu.schemas.asm.get_rets_diff_v1 import RmodConnector, VduAldBasic
from taf.gnb.oam.coam.vdu.schemas.asm.alarms import Alarm
from taf.gnb.oam.coam.vdu.schemas.asm.dist_names import DistNames


class VduRaeAldState(VduAldBasic):
    dc_power_sources = SchemaField(name='dc_power_sources', many=True, klass=RmodConnector, not_null=True)

    def __init__(self, id, configuration_id, product_code, serial_number, vendor_code, software_version,
                 hardware_version, control_protocol, aisg_protocol_version, release_id3_gpp, control_ports,
                 availability_status, operational_state, procedural_status, alarms, dist_names, dc_power_sources):
        self.id = id
        self.configuration_id = configuration_id
        self.product_code = product_code
        self.serial_number = serial_number
        self.vendor_code = vendor_code
        self.software_version = software_version
        self.hardware_version = hardware_version
        self.control_protocol = control_protocol
        self.aisg_protocol_version = aisg_protocol_version
        self.release_id3_gpp = release_id3_gpp
        self.control_ports = control_ports
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.procedural_status = procedural_status
        self.alarms = alarms
        self.dist_names = dist_names
        self.dc_power_sources = dc_power_sources

        super(VduRaeAldState, self).__init__(id, configuration_id, product_code, serial_number, vendor_code,
                                             software_version, hardware_version, control_protocol,
                                             aisg_protocol_version, release_id3_gpp, control_ports, availability_status,
                                             operational_state, procedural_status, alarms, dist_names)


class RaeAntennaInfo(SchemaObject):
    ant_model = SchemaField(name='ant_model', optional=True)
    ant_serial = SchemaField(name='ant_serial', optional=True)
    ant_bearing = SchemaField(name='ant_bearing', optional=True)
    install_date = SchemaField(name='install_date', optional=True)
    installer_id = SchemaField(name='installer_id', optional=True)
    base_station_id = SchemaField(name='base_station_id', optional=True)
    sector_id = SchemaField(name='sector_id', optional=True)
    ant_latitude = SchemaField(name='ant_latitude', optional=True)
    ant_altitude = SchemaField(name='ant_altitude', optional=True)
    ant_longitude = SchemaField(name='ant_longitude', optional=True)

    def __init__(self, ant_model, ant_serial, ant_bearing, install_date, installer_id, base_station_id, sector_id,
                 ant_latitude, ant_altitude, ant_longitude):
        self.ant_model = ant_model
        self.ant_serial = ant_serial
        self.ant_bearing = ant_bearing
        self.install_date = install_date
        self.installer_id = installer_id
        self.base_station_id = base_station_id
        self.sector_id = sector_id
        self.ant_latitude = ant_latitude
        self.ant_altitude = ant_altitude
        self.ant_longitude = ant_longitude

        super(RaeAntennaInfo, self).__init__()


class FunctionFlagInfo(SchemaObject):
    weighting_factor_flag = SchemaField(name='weighting_factor_flag')
    location_sensor_flag = SchemaField(name='location_sensor_flag')
    height_sensor_flag = SchemaField(name='height_sensor_flag')
    antenna_bearing_sensor_flag = SchemaField(name='antenna_bearing_sensor_flag')
    mechanical_tilt_sensor_flag = SchemaField(name='mechanical_tilt_sensor_flag')

    def __init__(self, weighting_factor_flag, location_sensor_flag, height_sensor_flag, antenna_bearing_sensor_flag,
                 mechanical_tilt_sensor_flag):
        self.weighting_factor_flag  = weighting_factor_flag
        self.location_sensor_flag = location_sensor_flag
        self.height_sensor_flag = height_sensor_flag
        self.antenna_bearing_sensor_flag = antenna_bearing_sensor_flag
        self.mechanical_tilt_sensor_flag = mechanical_tilt_sensor_flag

        super(FunctionFlagInfo, self).__init__()


class Raeu(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    alarms = SchemaField(name='alarms', klass=Alarm, not_null=True, many=True)
    antenna_info = SchemaField(name='antenna_info', klass=RaeAntennaInfo, optional=True)
    antenna_list = SchemaField(name='antenna_list', klass=RmodConnector, many=True, not_null=True)
    configuration_id = SchemaField(name='configuration_id')
    dist_names = SchemaField(name='dist_names', not_null=True, klass=DistNames)
    mechanical_angle = SchemaField(name='mechanical_angle', optional=True)
    availability_status = SchemaField(name='availability_status', optional=True)
    operational_state = SchemaField(name='operational_state', optional=True)
    procedural_status = SchemaField(name='procedural_status', optional=True)
    function_flags = SchemaField(name='function_flags', klass=FunctionFlagInfo, optional=True)

    def __init__(self, id, alarms, antenna_info, antenna_list, configuration_id, dist_names, mechanical_angle,
                 availability_status, operational_state, procedural_status, function_flags):
        self.id = id
        self.alarms = alarms
        self.antenna_info = antenna_info
        self.antenna_list = antenna_list
        self.configuration_id = configuration_id
        self.dist_names = dist_names
        self.mechanical_angle = mechanical_angle
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.procedural_status = procedural_status
        self.function_flags = function_flags

        super(Raeu, self).__init__()


class GetRAEsDiffV1(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    ald = SchemaField(name='ald', not_null=True, klass=VduRaeAldState)
    subunits = SchemaField(name='subunits', not_null=True, klass=Raeu, many=True)

    def __init__(self, id, ald, subunits):
        self.id = id
        self.ald = ald
        self.subunits = subunits

        super(GetRAEsDiffV1, self).__init__()
